async #initManualConfig(
  protocol,
  { previousStep = "protocolSelectSubview", clearHostnames = false } = {}
) {
  switch (protocol) {
    case "imap":
    case "pop3":
      await this.#initUI("manualConfigSubview");
      break;
    case "microsoft":
      await this.#initUI("exchangeSettingsSubview");
      break;
    default:
      throw new Error(`Invalid protocol [${protocol}] used.`);
  }
